(()=>{
'use strict';
const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function latestDate(registry){const dates=[registry.updated,...(registry.sources||[]).map(source=>source.checked),...(registry.records||[]).map(record=>record.sourceDate)].filter(Boolean).map(String).sort();return dates.at(-1)?.slice(0,10)||'Not recorded'}
function jurisdictionCount(records){return new Set(records.map(record=>String(record.jurisdiction||'').replace(/[^A-Za-zÀ-ÿ .'-]/g,'').trim()).filter(Boolean)).size}
function breakdown(records){const verified=records.filter(record=>record.financialMeasureVerified===true).length,profiled=records.filter(record=>record.identityVerified===true).length,ranked=records.filter(record=>record.financialMeasureVerified===true&&Number(record.rank)>0).length;return{verified,profiled,ranked,research:Math.max(0,records.length-verified)}}
async function load(){
  const response=await fetch('data/money-intelligence-registry.json',{cache:'no-store'});if(!response.ok)throw new Error('Money registry unavailable');const registry=await response.json();
  const records=registry.records||[],categories=registry.categories||[],all=breakdown(records);
  const stats=$('#money-command-stats');if(stats)stats.innerHTML=[['Tracked candidates',records.length.toLocaleString()],['Identity profiles',all.profiled.toLocaleString()],['Verified measures',all.verified.toLocaleString()],['Jurisdictions named',jurisdictionCount(records)],['Last checked',latestDate(registry)]].map(([label,value])=>`<div class="money-stat"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`).join('');
  const grid=$('#money-command-grid');if(grid)grid.innerHTML=categories.map(category=>{const rows=records.filter(record=>record.category===category.id),b=breakdown(rows),target=category.target||100,candidates=rows.length,verifiedPct=Math.min(100,Math.round(b.verified/target*100));return`<a class="money-command-card" href="${esc(category.route)}"><span>${candidates}/${target} candidates</span><strong>${esc(category.title)}</strong><small>${esc(category.rankingStatus||'Public-record registry')}</small><div class="money-coverage-bar" title="${b.verified} of ${target} individually measure-verified"><i style="width:${verifiedPct}%"></i></div><em>${b.profiled} identity-profiled · ${b.ranked} ranked · ${b.verified} measure-verified · ${b.research} pending</em></a>`}).join('');
  const overlap=$('#money-overlap-preview');if(overlap){let graph=null;try{const graphResponse=await fetch('data/money-overlap-graph.json',{cache:'no-store'});if(graphResponse.ok)graph=await graphResponse.json()}catch{}const summary=graph?.summary||registry.overlapSummary||{};overlap.innerHTML=`<article class="money-card"><div class="money-kicker">Relationship intelligence</div><h2>${Number(summary.overlapEntities||0).toLocaleString()} cross-category identities</h2><p>${Number(summary.relationshipEdges||0).toLocaleString()} sourced relationship records feed the overlap layer alongside conservative name-normalised category matches.</p><a class="btn" href="money-graph.html">Open overlap map</a></article><article class="money-card"><div class="money-kicker">Coverage truth</div><h2>CANDIDATES ARE NOT VERIFIED RANKINGS.</h2><p>The cards now separate candidate count, identity resolution, dated ranking and individually verified measurement. Missing private disclosure stays visibly pending.</p><a class="btn alt" href="follow-the-money-methodology.html">Read methodology</a></article>`}
}
load().catch(error=>{const target=$('#money-command-center');if(target)target.insertAdjacentHTML('beforeend',`<p class="money-warning"><strong>Registry status:</strong> ${esc(error.message)}</p>`)});
})();
